/* Structured section editing. Revision history is scoped to this browser session. */
const sectionBlocks={},sectionVersions={};
let blockSaveTimer;
function sectionKey(){return selected+':'+sectionIndex}
function getSectionBlocks(){const key=sectionKey();if(!sectionBlocks[key]||sectionBlocks[key].plain!==docs()[sectionIndex])sectionBlocks[key]={plain:docs()[sectionIndex],blocks:docs()[sectionIndex].split(/\n\s*\n/).map(text=>({type:'paragraph',text}))};return sectionBlocks[key].blocks}
function blockMarkup(b,i){const tag={paragraph:'p',heading:'h2',bullet:'p',quote:'blockquote'}[b.type]||'p';return '<div class="srs-block" data-block="'+i+'"><div class="block-controls"><select aria-label="Block '+(i+1)+' type" onchange="changeBlockType('+i+',this.value)" '+(current().approved?'disabled':'')+'>'+[['paragraph','Text'],['heading','Heading'],['bullet','• List item'],['quote','Quote']].map(([v,t])=>'<option value="'+v+'" '+(b.type===v?'selected':'')+'>'+t+'</option>').join('')+'</select><button type="button" aria-label="Move block up" onclick="moveSrsBlock('+i+',-1)">↑</button><button type="button" aria-label="Move block down" onclick="moveSrsBlock('+i+',1)">↓</button><button type="button" aria-label="Delete block" onclick="deleteSrsBlock('+i+')">×</button></div><'+tag+' class="block-text '+(b.type==='bullet'?'bullet-block':'')+'" contenteditable="'+(!current().approved)+'" role="textbox" aria-multiline="true" aria-label="Block '+(i+1)+'" data-placeholder="Start writing this section…" oninput="this.dataset.empty=String(!this.textContent.trim());queueBlockSave()" onblur="sectionSave()" onpaste="pasteBlockText(event)">'+esc(b.text)+'</'+tag+'></div>'}
function recordSectionVersion(reason,blocks){const key=sectionKey(),list=sectionVersions[key]||(sectionVersions[key]=[]),text=blocks.map(b=>b.text).join('\n\n');if(list.length&&JSON.stringify(list.at(-1).blocks)===JSON.stringify(blocks))return;list.push({time:new Date().toISOString(),author:profile.name,reason,blocks:JSON.parse(JSON.stringify(blocks)),text})}
sectionSave=function(){const root=document.getElementById('srsBlocks');if(!root||current().approved)return;const blocks=getSectionBlocks(),nodes=root.querySelectorAll('.block-text');nodes.forEach((el,i)=>{if(blocks[i])blocks[i].text=el.innerText});const text=blocks.map(b=>b.text).join('\n\n');recordSectionVersion('Edited',blocks);docs()[sectionIndex]=text;sectionBlocks[sectionKey()].plain=text;current().reviewed=false;const status=document.getElementById('srsSaveStatus');if(status)status.textContent='Saved in this session · '+new Date().toLocaleTimeString()};
function queueBlockSave(){clearTimeout(blockSaveTimer);const status=document.getElementById('srsSaveStatus');if(status)status.textContent='Saving…';blockSaveTimer=setTimeout(sectionSave,800)}
function pasteBlockText(e){e.preventDefault();const text=e.clipboardData.getData('text/plain'),sel=window.getSelection();if(!sel.rangeCount)return;const r=sel.getRangeAt(0);r.deleteContents();const node=document.createTextNode(text);r.insertNode(node);r.setStartAfter(node);r.collapse(true);sel.removeAllRanges();sel.addRange(r);queueBlockSave()}
function mutateBlocks(change){if(current().approved)return;sectionSave();const blocks=getSectionBlocks();change(blocks);recordSectionVersion('Block change',blocks);docs()[sectionIndex]=blocks.map(b=>b.text).join('\n\n');sectionBlocks[sectionKey()].plain=docs()[sectionIndex];current().reviewed=false;render()}
function changeBlockType(i,type){mutateBlocks(b=>b[i].type=type)}
function moveSrsBlock(i,delta){mutateBlocks(b=>{const next=i+delta;if(next>=0&&next<b.length)[b[i],b[next]]=[b[next],b[i]]})}
function deleteSrsBlock(i){mutateBlocks(b=>{b.splice(i,1);if(!b.length)b.push({type:'paragraph',text:''})})}
function addSrsBlock(){mutateBlocks(b=>b.push({type:'paragraph',text:''}));document.querySelector('#srsBlocks .srs-block:last-child .block-text')?.focus()}
function showSectionVersions(){sectionSave();const list=sectionVersions[sectionKey()]||[],box=document.getElementById('modal');box.innerHTML='<h2>Section version history</h2><p class="sub">'+esc(sectionTitles[sectionIndex])+' · This browser session only. Shared live editing is not connected.</p><div class="revision-list">'+list.slice().reverse().map((v,j)=>'<section><strong>Version '+(list.length-j)+'</strong><small>'+esc(v.author)+' · '+new Date(v.time).toLocaleString()+'</small><p>'+esc(v.reason)+'</p><details><summary>View content</summary><pre>'+esc(v.text)+'</pre></details><button '+(current().approved?'disabled':'')+' onclick="restoreSectionVersion('+(list.length-1-j)+')">Restore version</button></section>').join('')+'</div><button onclick="document.getElementById(\'modal\').close()">Close</button>';box.showModal()}
function restoreSectionVersion(i){if(current().approved)return;const v=sectionVersions[sectionKey()][i];sectionBlocks[sectionKey()]={blocks:JSON.parse(JSON.stringify(v.blocks)),plain:v.text};docs()[sectionIndex]=v.text;recordSectionVersion('Restored version '+(i+1),v.blocks);current().reviewed=false;document.getElementById('modal').close();render();toast('Section restored. The previous version remains in history.')}
function requestSectionRewrite(action){sectionSave();const status=document.getElementById('rewriteStatus');status.textContent='AI rewriting is not connected. Your section has not been changed.';status.setAttribute('role','status')}
// Never append a generic instruction to a user's document.
proposeSectionAI=function(){requestSectionRewrite()};proposeSectionPrompt=function(){requestSectionRewrite()};
acceptSectionAI=function(){toast('No generated replacement is available. Your content is unchanged.')};
blueprintPageRoutes.srs=function(){const blocks=getSectionBlocks();if(!sectionVersions[sectionKey()])recordSectionVersion('Initial version',blocks);return appNav()+bpHeading('Software requirements specification','',button('Version history','showSectionVersions()')+button('Export','exportSections()')+button('Review baseline →',"navigate('baseline')",true))+'<div class="srs-workspace block-workspace"><section class="section-list"><h2>Sections</h2>'+sectionTitles.map((t,i)=>'<button class="'+(i===sectionIndex?'selected':'')+'" onclick="chooseSection('+i+')">'+(i+1)+'. '+t+'</button>').join('')+'</section><section class="srs-editor panel"><div class="editor-title"><h2>'+esc(sectionTitles[sectionIndex])+'</h2>'+badge(current().approved?'Approved':'Draft')+'</div><div class="block-toolbar"><span>Text · headings · lists · quotes</span>'+button('+ Block','addSrsBlock()')+'</div><div id="srsBlocks">'+blocks.map(blockMarkup).join('')+'</div><div class="editor-footer"><span id="srsSaveStatus">Saved in this session</span></div></section><section class="ai-edit-panel panel"><h2>✦ Edit with AI</h2><p class="sub">Rewrite the entire selected section using an action and your instructions.</p><label class="field">Action<select id="rewriteAction"><option>Improve writing</option><option>Expand content</option><option>Shorten content</option><option>Clarify acceptance criteria</option><option>Check assumptions</option></select></label><label class="field">Instructions<textarea id="sectionAiPrompt" placeholder="Describe how this section should change"></textarea></label>'+button('Rewrite section','requestSectionRewrite()',true)+'<p id="rewriteStatus" class="sub">AI service not connected. Rewriting is unavailable.</p><p class="sub">Version history is local to this session. Simultaneous multi-user editing requires a shared collaboration service.</p></section></div>'};
const renderBlockBase=render;
render=function(){renderBlockBase();document.body.classList.toggle('srs-fixed',screen==='srs');};
const workflowPages=['request','srs','baseline','requirements','stories','timeline','architecture','tests','quality'];
const navigateBlockBase=navigate;
let workflowNavigationPending=false;
navigate=function(route){if(workflowNavigationPending)return;if(workflowPages.includes(route)&&route!==screen){sectionSave();workflowNavigationPending=true;const overlay=document.createElement('div');overlay.className='workflow-loading';overlay.setAttribute('role','status');overlay.innerHTML='<span class="workflow-spinner"></span><b>Opening '+esc(pageNames[route]||route)+'…</b>';document.body.appendChild(overlay);requestAnimationFrame(()=>requestAnimationFrame(()=>{try{navigateBlockBase(route)}finally{overlay.remove();workflowNavigationPending=false}}));}else navigateBlockBase(route)};
window.addEventListener('beforeunload',sectionSave);
render();
// Single WYSIWYG surface; keep section history and plain-text exports compatible.
const richSections={};
function richMarkup(){const key=sectionKey();return richSections[key]?.plain===docs()[sectionIndex]?(richSections[key].html||'<p><br></p>'):docs()[sectionIndex].split('\n\n').map(p=>'<p>'+esc(p).replaceAll('\n','<br>')+'</p>').join('')}
sectionSave=function(){const el=document.getElementById('srsRichEditor');if(!el||current().approved)return;const empty=!el.textContent.trim();if(empty&&!el.querySelector('p'))el.innerHTML='<p><br></p>';el.dataset.empty=String(empty);const text=empty?'':el.innerText,html=el.innerHTML;const key=sectionKey();if(richSections[key]?.html!==html){const blocks=[{type:'paragraph',text}];recordSectionVersion('Edited',blocks);const list=sectionVersions[key];if(list?.length)list[list.length-1].html=html;docs()[sectionIndex]=text;richSections[key]={plain:text,html};current().reviewed=false}const status=document.getElementById('srsSaveStatus');if(status)status.textContent='Saved in this session'};
function richCommand(command,value=null){if(current().approved)return;document.getElementById('srsRichEditor').focus();document.execCommand(command,false,value);sectionSave()}
restoreSectionVersion=function(i){if(current().approved)return;const v=sectionVersions[sectionKey()][i];docs()[sectionIndex]=v.text;richSections[sectionKey()]={plain:v.text,html:v.html||'<p>'+esc(v.text).replaceAll('\n','<br>')+'</p>'};recordSectionVersion('Restored version '+(i+1),v.blocks);current().reviewed=false;document.getElementById('modal').close();render()};
blueprintPageRoutes.srs=function(){if(!sectionVersions[sectionKey()])recordSectionVersion('Initial version',[{type:'paragraph',text:docs()[sectionIndex]}]);const readonly=current().approved;return appNav()+bpHeading('Software requirements specification','Review and refine each section.',button('Version history','showSectionVersions()')+button('Export','exportSections()')+button('Review baseline →',"navigate('baseline')",true))+'<div class="srs-workspace rich-workspace"><section class="section-list"><h2>Sections</h2>'+sectionTitles.map((t,i)=>'<button class="'+(i===sectionIndex?'selected':'')+'" onclick="chooseSection('+i+')">'+(i+1)+'. '+t+'</button>').join('')+'</section><section class="srs-editor panel"><div class="editor-title"><h2>'+esc(sectionTitles[sectionIndex])+'</h2>'+badge(readonly?'Approved':'Draft')+'</div><div class="rich-toolbar" role="toolbar" aria-label="Text formatting"><select aria-label="Paragraph style" '+(readonly?'disabled':'')+' onchange="richCommand(\'formatBlock\',this.value)"><option value="p">Paragraph</option><option value="h2">Heading 1</option><option value="h3">Heading 2</option><option value="blockquote">Quote</option></select>'+[['bold','B','Bold'],['italic','I','Italic'],['underline','U','Underline'],['insertUnorderedList','• List','Bullet list'],['insertOrderedList','1. List','Numbered list'],['undo','↶','Undo'],['redo','↷','Redo']].map(([cmd,label,title])=>'<button type="button" aria-label="'+title+'" title="'+title+'" '+(readonly?'disabled':'')+' onmousedown="event.preventDefault()" onclick="richCommand(\''+cmd+'\')">'+label+'</button>').join('')+'</div><div id="srsRichEditor" role="textbox" aria-label="Section content" aria-multiline="true" contenteditable="'+(!readonly)+'" data-placeholder="Start writing this section…" oninput="this.dataset.empty=String(!this.textContent.trim());queueBlockSave()" onblur="sectionSave()" onpaste="pasteBlockText(event)">'+richMarkup()+'</div><div class="editor-footer"><span id="srsSaveStatus">Saved in this session</span>'+button('Save section','sectionSave()')+'</div></section><section class="ai-edit-panel panel"><h2>✦ Edit with AI</h2><p class="sub">Choose how to refine this section.</p>'+['Improve writing','Expand content','Shorten content','Clarify acceptance criteria','Check assumptions'].map(t=>'<button onclick="requestSectionRewrite(\''+t+'\')">'+icon('requirements')+t+'</button>').join('')+'<label class="field">Prompt AI for this section<textarea id="sectionAiPrompt" placeholder="Describe the changes you want"></textarea></label>'+button('Generate suggestion','requestSectionRewrite()')+'<p id="rewriteStatus" class="sub">AI service not connected. Your content remains unchanged.</p></section></div>'};
const renderRichBase=render;
let lastRichScreen='';
render=function(){renderRichBase();if(screen==='srs'&&lastRichScreen!=='srs'){window.scrollTo?.({top:0,behavior:'instant'});document.querySelector('.bp-main')?.scrollTo?.({top:0,behavior:'instant'})}lastRichScreen=screen};
navigate=function(route){if(workflowNavigationPending)return;if(workflowPages.includes(route)&&route!==screen){captureReq();workflowNavigationPending=true;const overlay=document.createElement('div');overlay.className='workflow-loading';overlay.setAttribute('role','status');overlay.setAttribute('aria-live','polite');overlay.innerHTML='<span class="workflow-spinner"></span><div><b>'+(route==='srs'?'Preparing SRS…':'Opening '+esc(pageNames[route]||route)+'…')+'</b><p>Loading your workspace</p></div>';document.body.appendChild(overlay);setTimeout(()=>{try{navigateBlockBase(route);window.scrollTo?.({top:0,behavior:'instant'})}finally{overlay.remove();workflowNavigationPending=false}},650)}else navigateBlockBase(route)};
render();
